def unionIntervals(firstList, secondList):
    a, b = firstList, secondList
    i = j = 0
    res = []
    while i < len(a) or j < len(b):
        if j == len(b) or (i < len(a) and a[i][0] <= b[j][0]):
            s, e = a[i]
            i += 1
        else:
            s, e = b[j]
            j += 1
        if res and s <= res[-1][1]:
            if e > res[-1][1]:
                res[-1][1] = e
        else:
            res.append([s, e])
    return res
